module counter_12 (
    input rst_n,
    input clk,
    input valid_count,
    output reg [3:0] out
);
    parameter MAX_COUNT = 4'd11;

    reg [3:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 4'b0000;
        end else if (valid_count) begin
            if (count_reg == MAX_COUNT) begin
                count_reg <= 4'b0000;
            end else begin
                count_reg <= count_reg + 1;
            end
        end
    end

    assign out = count_reg;
endmodule
